#include <stdio.h>

#define MAX_BOWLS 4

int bowls[MAX_BOWLS];
int top = 0;

int push(int value) {
    if (top == MAX_BOWLS) {
        return 0;
    }
    bowls[top] = value;
    top++;
    return 1;
}

int pop(int *value) {
    if (top == 0) {
        return 0;
    }
    top--;
    *value = bowls[top];
    return 1;
}

int main(void) {
    push(7);
    push(8);
    push(9);
    int v = 0;
    pop(&v);
    printf("%d\n", v);
    pop(&v);
    printf("%d\n", v);
    printf("还剩 %d 只碗\n", top);
    return 0;
}

#include <stdio.h>

#define MAX_CATS 5

int line[MAX_CATS];
int head = 0;
int tail = 0;

int enqueue(int value) {
    if (tail == MAX_CATS) {
        return 0;
    }
    line[tail] = value;
    tail++;
    return 1;
}

int dequeue(int *value) {
    if (head == tail) {
        return 0;
    }
    *value = line[head];
    head++;
    return 1;
}

int main(void) {
    enqueue(1);
    enqueue(2);
    enqueue(3);
    int v = 0;
    dequeue(&v);
    printf("第一个领到 %d\n", v);
    enqueue(4);
    while (dequeue(&v)) {
        printf("接着领到 %d\n", v);
    }
    return 0;
}
